import type { MapMemberEvidence } from "./mapEvidence";
import { sha256 } from "./tidyRun";
import { WorkflowOperationError } from "./workflowOutcome";

/** Render a new draft with explicit generated bytes. Public markers and hashes
 * describe content only; they never confer native refresh or undo authority. */
export async function renderMapDraft(
  cluster: string,
  body: string,
  evidence: MapMemberEvidence[],
  created: string,
): Promise<string> {
  if (!body.trim() || body.includes("\0") ||
      /<!--\s*\/?myco:map-generated/i.test(body) ||
      /<!--\s*\/?myco:map-generated/i.test(cluster)) {
    throw new WorkflowOperationError("pending", "validation_rejected",
      "Topic map output is empty or contains reserved generated-section markers; retry required");
  }
  const generated = `${body.trim()}\n`;
  const descriptor = { version: 1, bodyRevision: await sha256(generated) };
  const sources = { version: 1, members: evidence.map(({ path, revision, sourceChars, excerpt, truncated }) =>
    ({ path, revision, sourceChars, excerptChars: Array.from(excerpt).length, truncated })) };
  return `---\n` +
    `title: ${JSON.stringify(`Map: ${cluster}`)}\n` +
    `type: map\n` +
    `cluster: ${JSON.stringify(cluster)}\n` +
    `created: ${created}\n` +
    `confidence: medium\n` +
    `status: draft\n` +
    `map_evidence: ${JSON.stringify(sources)}\n` +
    `map_generated: ${JSON.stringify(descriptor)}\n` +
    `tags: [map]\n` +
    `---\n\n<!-- myco:map-generated:v1 -->\n${generated}<!-- /myco:map-generated -->\n`;
}
